insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('839f1d6f-22c8-4a1c-9024-8e3f0bb28805', 'e277c175-61a0-487d-98f2-25f031973da1', null, 'topic'::public.curated_course_node_type, 'Probability models', 'This module establishes probability models as the course''s first working framework. It supplies the language and representations needed before the path advances to conditioning and independence.', 0),
  ('75b42b2b-14c2-4959-914f-df8baef451a8', 'e277c175-61a0-487d-98f2-25f031973da1', '839f1d6f-22c8-4a1c-9024-8e3f0bb28805', 'subtopic'::public.curated_course_node_type, 'Sample spaces', 'Sample spaces gives probability models a reusable representation for organizing assumptions, variables, and relationships before analysis begins. It appears before axioms because that next topic assumes this starting point.', 0),
  ('5c8440d6-675b-40c5-b586-dd734c2e61c8', 'e277c175-61a0-487d-98f2-25f031973da1', '839f1d6f-22c8-4a1c-9024-8e3f0bb28805', 'subtopic'::public.curated_course_node_type, 'Axioms', 'Axioms provides a formal guarantee or inference rule for probability models, allowing later conclusions to be justified rather than inferred from examples alone. After sample spaces, axioms supplies what is needed to address counting.', 1),
  ('5c8bada8-ef9e-48cd-8745-8595c60bf794', 'e277c175-61a0-487d-98f2-25f031973da1', '839f1d6f-22c8-4a1c-9024-8e3f0bb28805', 'subtopic'::public.curated_course_node_type, 'Counting', 'Counting identifies a specific object, distinction, or relationship within probability models. Learners need to recognize and use it before combining this module''s ideas in later work. After axioms, counting supplies what is needed to address set operations.', 2),
  ('d4e23221-fffa-4079-a396-f32160fcbe98', 'e277c175-61a0-487d-98f2-25f031973da1', '839f1d6f-22c8-4a1c-9024-8e3f0bb28805', 'subtopic'::public.curated_course_node_type, 'Set operations', 'Set operations identifies a specific object, distinction, or relationship within probability models. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, set operations carries the completed idea into conditioning and independence.', 3),
  ('3b6d6e4e-9cae-4c09-896b-5093ab6d2be8', 'e277c175-61a0-487d-98f2-25f031973da1', null, 'topic'::public.curated_course_node_type, 'Conditioning and independence', 'This module builds directly on probability models and develops conditioning and independence. It belongs here because its methods and distinctions are prerequisites for discrete random variables.', 1),
  ('f8ed7aba-1319-4a02-b9b4-039f43216491', 'e277c175-61a0-487d-98f2-25f031973da1', '3b6d6e4e-9cae-4c09-896b-5093ab6d2be8', 'subtopic'::public.curated_course_node_type, 'Bayes’ rule', 'Bayes’ rule identifies a specific object, distinction, or relationship within conditioning and independence. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before total probability because that next topic assumes this starting point.', 0),
  ('e76443a0-b1e8-4fec-b657-e124327b1689', 'e277c175-61a0-487d-98f2-25f031973da1', '3b6d6e4e-9cae-4c09-896b-5093ab6d2be8', 'subtopic'::public.curated_course_node_type, 'Total probability', 'Total probability is a governing quantity in conditioning and independence, linking local calculations to system-level behavior and offering a consistency check. After bayes’ rule, total probability supplies what is needed to address conditional independence.', 1),
  ('e10229b7-c2ee-415f-b64c-fd8de1763371', 'e277c175-61a0-487d-98f2-25f031973da1', '3b6d6e4e-9cae-4c09-896b-5093ab6d2be8', 'subtopic'::public.curated_course_node_type, 'Conditional independence', 'Conditional independence identifies a specific object, distinction, or relationship within conditioning and independence. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, conditional independence carries the completed idea into discrete random variables.', 2),
  ('cfeb1752-0a80-4e25-9fc3-77e73625e7bf', 'e277c175-61a0-487d-98f2-25f031973da1', null, 'topic'::public.curated_course_node_type, 'Discrete random variables', 'This module builds directly on conditioning and independence and develops discrete random variables. It belongs here because its methods and distinctions are prerequisites for continuous random variables.', 2),
  ('fbd0ccfc-b5e8-4b8c-8ebb-bfb10b20941c', 'e277c175-61a0-487d-98f2-25f031973da1', 'cfeb1752-0a80-4e25-9fc3-77e73625e7bf', 'subtopic'::public.curated_course_node_type, 'PMFs', 'PMFs identifies a specific object, distinction, or relationship within discrete random variables. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before expectation because that next topic assumes this starting point.', 0),
  ('ff8649fe-b4f1-4a43-acdb-5b7c7b23b1f5', 'e277c175-61a0-487d-98f2-25f031973da1', 'cfeb1752-0a80-4e25-9fc3-77e73625e7bf', 'subtopic'::public.curated_course_node_type, 'Expectation', 'Expectation identifies a specific object, distinction, or relationship within discrete random variables. Learners need to recognize and use it before combining this module''s ideas in later work. After pmfs, expectation supplies what is needed to address transforms.', 1),
  ('6c4f0c41-1384-4a7c-811f-c7ceb98c939c', 'e277c175-61a0-487d-98f2-25f031973da1', 'cfeb1752-0a80-4e25-9fc3-77e73625e7bf', 'subtopic'::public.curated_course_node_type, 'Transforms', 'Transforms makes difficult behavior in discrete random variables tractable while exposing the assumptions and accuracy limits used by later methods. After expectation, transforms supplies what is needed to address bernoulli/binomial/poisson.', 2),
  ('d47cf5c0-f1e4-4b76-adb6-ecde0050d80f', 'e277c175-61a0-487d-98f2-25f031973da1', 'cfeb1752-0a80-4e25-9fc3-77e73625e7bf', 'subtopic'::public.curated_course_node_type, 'Bernoulli/binomial/Poisson', 'Bernoulli/binomial/Poisson identifies a specific object, distinction, or relationship within discrete random variables. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, bernoulli/binomial/poisson carries the completed idea into continuous random variables.', 3),
  ('820ac4b3-c197-4a2d-b1f4-dde9d0d043af', 'e277c175-61a0-487d-98f2-25f031973da1', null, 'topic'::public.curated_course_node_type, 'Continuous random variables', 'This module builds directly on discrete random variables and develops continuous random variables. It belongs here because its methods and distinctions are prerequisites for joint distributions.', 3),
  ('a1bef6f3-f45b-46b0-ad8d-ca1fd5de6ddb', 'e277c175-61a0-487d-98f2-25f031973da1', '820ac4b3-c197-4a2d-b1f4-dde9d0d043af', 'subtopic'::public.curated_course_node_type, 'Densities', 'Densities identifies a specific object, distinction, or relationship within continuous random variables. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before cdfs because that next topic assumes this starting point.', 0),
  ('53cbc07a-9143-4369-9f6d-706380570aec', 'e277c175-61a0-487d-98f2-25f031973da1', '820ac4b3-c197-4a2d-b1f4-dde9d0d043af', 'subtopic'::public.curated_course_node_type, 'CDFs', 'CDFs identifies a specific object, distinction, or relationship within continuous random variables. Learners need to recognize and use it before combining this module''s ideas in later work. After densities, cdfs supplies what is needed to address gaussian/exponential families.', 1),
  ('39978fb0-de24-4481-8032-161bd179ef65', 'e277c175-61a0-487d-98f2-25f031973da1', '820ac4b3-c197-4a2d-b1f4-dde9d0d043af', 'subtopic'::public.curated_course_node_type, 'Gaussian/exponential families', 'Gaussian/exponential families identifies a specific object, distinction, or relationship within continuous random variables. Learners need to recognize and use it before combining this module''s ideas in later work. After cdfs, gaussian/exponential families supplies what is needed to address transformations.', 2),
  ('516bee0c-230f-47e7-a743-a525257453dc', 'e277c175-61a0-487d-98f2-25f031973da1', '820ac4b3-c197-4a2d-b1f4-dde9d0d043af', 'subtopic'::public.curated_course_node_type, 'Transformations', 'Transformations makes difficult behavior in continuous random variables tractable while exposing the assumptions and accuracy limits used by later methods. As the final topic in this module, transformations carries the completed idea into joint distributions.', 3),
  ('a6cc48da-370b-4352-b284-87070c162101', 'e277c175-61a0-487d-98f2-25f031973da1', null, 'topic'::public.curated_course_node_type, 'Joint distributions', 'This module builds directly on continuous random variables and develops joint distributions. It belongs here because its methods and distinctions are prerequisites for expectation tools.', 4),
  ('9235e124-e305-422f-8013-8a2401d46f78', 'e277c175-61a0-487d-98f2-25f031973da1', 'a6cc48da-370b-4352-b284-87070c162101', 'subtopic'::public.curated_course_node_type, 'Covariance', 'Covariance identifies a specific object, distinction, or relationship within joint distributions. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before correlation because that next topic assumes this starting point.', 0),
  ('608aabbd-17e5-4239-a365-7c389cf73962', 'e277c175-61a0-487d-98f2-25f031973da1', 'a6cc48da-370b-4352-b284-87070c162101', 'subtopic'::public.curated_course_node_type, 'Correlation', 'Correlation identifies a specific object, distinction, or relationship within joint distributions. Learners need to recognize and use it before combining this module''s ideas in later work. After covariance, correlation supplies what is needed to address conditioning.', 1),
  ('6caa79d8-36be-4684-a348-caa0828ef8b5', 'e277c175-61a0-487d-98f2-25f031973da1', 'a6cc48da-370b-4352-b284-87070c162101', 'subtopic'::public.curated_course_node_type, 'Conditioning', 'Conditioning identifies a specific object, distinction, or relationship within joint distributions. Learners need to recognize and use it before combining this module''s ideas in later work. After correlation, conditioning supplies what is needed to address independence.', 2),
  ('a1ed32cb-2a2e-4ef6-bf72-c8f9e66a2f42', 'e277c175-61a0-487d-98f2-25f031973da1', 'a6cc48da-370b-4352-b284-87070c162101', 'subtopic'::public.curated_course_node_type, 'Independence', 'Independence identifies a specific object, distinction, or relationship within joint distributions. Learners need to recognize and use it before combining this module''s ideas in later work. After conditioning, independence supplies what is needed to address sums.', 3),
  ('cc5939c4-f3a7-4120-b9be-9fd1624f4d83', 'e277c175-61a0-487d-98f2-25f031973da1', 'a6cc48da-370b-4352-b284-87070c162101', 'subtopic'::public.curated_course_node_type, 'Sums', 'Sums identifies a specific object, distinction, or relationship within joint distributions. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, sums carries the completed idea into expectation tools.', 4),
  ('91cc8de7-295f-463d-9a25-84281b998d1e', 'e277c175-61a0-487d-98f2-25f031973da1', null, 'topic'::public.curated_course_node_type, 'Expectation tools', 'This module builds directly on joint distributions and develops expectation tools. It belongs here because its methods and distinctions are prerequisites for limit theorems.', 5),
  ('02170c3a-1755-456f-8f0f-77ad01c00a6a', 'e277c175-61a0-487d-98f2-25f031973da1', '91cc8de7-295f-463d-9a25-84281b998d1e', 'subtopic'::public.curated_course_node_type, 'LOTUS', 'LOTUS identifies a specific object, distinction, or relationship within expectation tools. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before total expectation/variance because that next topic assumes this starting point.', 0),
  ('746c813c-b4e6-4deb-9cda-7015a4b72a93', 'e277c175-61a0-487d-98f2-25f031973da1', '91cc8de7-295f-463d-9a25-84281b998d1e', 'subtopic'::public.curated_course_node_type, 'Total expectation/variance', 'Total expectation/variance identifies a specific object, distinction, or relationship within expectation tools. Learners need to recognize and use it before combining this module''s ideas in later work. After lotus, total expectation/variance supplies what is needed to address moment generating functions.', 1),
  ('72819b88-6d18-4301-b1ad-bf18a7281e4c', 'e277c175-61a0-487d-98f2-25f031973da1', '91cc8de7-295f-463d-9a25-84281b998d1e', 'subtopic'::public.curated_course_node_type, 'Moment generating functions', 'Moment generating functions identifies a specific object, distinction, or relationship within expectation tools. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, moment generating functions carries the completed idea into limit theorems.', 2),
  ('48da4dd1-07a6-4674-9372-629958da3dd4', 'e277c175-61a0-487d-98f2-25f031973da1', null, 'topic'::public.curated_course_node_type, 'Limit theorems', 'This module builds directly on expectation tools and develops limit theorems. It belongs here because its methods and distinctions are prerequisites for estimation foundations.', 6),
  ('6a8599e0-4a65-403b-8586-1f16fbe97633', 'e277c175-61a0-487d-98f2-25f031973da1', '48da4dd1-07a6-4674-9372-629958da3dd4', 'subtopic'::public.curated_course_node_type, 'Laws of large numbers', 'Laws of large numbers provides a formal guarantee or inference rule for limit theorems, allowing later conclusions to be justified rather than inferred from examples alone. It appears before central limit theorem because that next topic assumes this starting point.', 0),
  ('b05cc899-c0c3-4399-ac4d-19799f47e7db', 'e277c175-61a0-487d-98f2-25f031973da1', '48da4dd1-07a6-4674-9372-629958da3dd4', 'subtopic'::public.curated_course_node_type, 'Central limit theorem', 'Central limit theorem provides a formal guarantee or inference rule for limit theorems, allowing later conclusions to be justified rather than inferred from examples alone. After laws of large numbers, central limit theorem supplies what is needed to address approximations.', 1),
  ('1af0baa4-5090-4cb6-a2af-c51fe14098d7', 'e277c175-61a0-487d-98f2-25f031973da1', '48da4dd1-07a6-4674-9372-629958da3dd4', 'subtopic'::public.curated_course_node_type, 'Approximations', 'Approximations makes difficult behavior in limit theorems tractable while exposing the assumptions and accuracy limits used by later methods. As the final topic in this module, approximations carries the completed idea into estimation foundations.', 2),
  ('3ef270ac-a5ef-4bd6-a936-dc31a78e90a8', 'e277c175-61a0-487d-98f2-25f031973da1', null, 'topic'::public.curated_course_node_type, 'Estimation foundations', 'This module builds directly on limit theorems and develops estimation foundations. It belongs here because its methods and distinctions are prerequisites for random-process models.', 7),
  ('3b7c0099-41ce-4ab1-b0ad-c9b2c5d9fc36', 'e277c175-61a0-487d-98f2-25f031973da1', '3ef270ac-a5ef-4bd6-a936-dc31a78e90a8', 'subtopic'::public.curated_course_node_type, 'MMSE', 'MMSE identifies a specific object, distinction, or relationship within estimation foundations. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before linear estimation because that next topic assumes this starting point.', 0),
  ('5b0e6dab-fa42-4ddf-9abb-88762f5ce7ae', 'e277c175-61a0-487d-98f2-25f031973da1', '3ef270ac-a5ef-4bd6-a936-dc31a78e90a8', 'subtopic'::public.curated_course_node_type, 'Linear estimation', 'Linear estimation identifies a specific object, distinction, or relationship within estimation foundations. Learners need to recognize and use it before combining this module''s ideas in later work. After mmse, linear estimation supplies what is needed to address map/ml viewpoints.', 1),
  ('8bb0d19a-1de5-498e-8491-f5c9c740b674', 'e277c175-61a0-487d-98f2-25f031973da1', '3ef270ac-a5ef-4bd6-a936-dc31a78e90a8', 'subtopic'::public.curated_course_node_type, 'MAP/ML viewpoints', 'MAP/ML viewpoints gives estimation foundations a reusable representation for organizing assumptions, variables, and relationships before analysis begins. As the final topic in this module, map/ml viewpoints carries the completed idea into random-process models.', 2),
  ('6077c91f-b829-4907-8257-650365116106', 'e277c175-61a0-487d-98f2-25f031973da1', null, 'topic'::public.curated_course_node_type, 'Random-process models', 'This module builds directly on estimation foundations and develops random-process models. It belongs here because its methods and distinctions are prerequisites for stationarity and ergodicity.', 8),
  ('30170928-d6f6-4e97-acbc-da9b4765829f', 'e277c175-61a0-487d-98f2-25f031973da1', '6077c91f-b829-4907-8257-650365116106', 'subtopic'::public.curated_course_node_type, 'Ensembles', 'Ensembles identifies a specific object, distinction, or relationship within random-process models. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before finite-dimensional distributions because that next topic assumes this starting point.', 0),
  ('0ebb9dd7-b372-4721-81dd-6ab66a98cd8b', 'e277c175-61a0-487d-98f2-25f031973da1', '6077c91f-b829-4907-8257-650365116106', 'subtopic'::public.curated_course_node_type, 'Finite-dimensional distributions', 'Finite-dimensional distributions gives random-process models a reusable representation for organizing assumptions, variables, and relationships before analysis begins. After ensembles, finite-dimensional distributions supplies what is needed to address mean/covariance.', 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('39dfeae9-4425-4b56-81d4-30c59900a2cb', 'e277c175-61a0-487d-98f2-25f031973da1', '6077c91f-b829-4907-8257-650365116106', 'subtopic'::public.curated_course_node_type, 'Mean/covariance', 'Mean/covariance identifies a specific object, distinction, or relationship within random-process models. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, mean/covariance carries the completed idea into stationarity and ergodicity.', 2),
  ('4e2e6a1d-45a2-4cb7-bf49-d28176538854', 'e277c175-61a0-487d-98f2-25f031973da1', null, 'topic'::public.curated_course_node_type, 'Stationarity and ergodicity', 'This module builds directly on random-process models and develops stationarity and ergodicity. It belongs here because its methods and distinctions are prerequisites for spectral analysis and lti systems.', 9),
  ('05922ee3-fc55-4370-8274-5bc251e8df5a', 'e277c175-61a0-487d-98f2-25f031973da1', '4e2e6a1d-45a2-4cb7-bf49-d28176538854', 'subtopic'::public.curated_course_node_type, 'WSS', 'WSS identifies a specific object, distinction, or relationship within stationarity and ergodicity. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before time averages because that next topic assumes this starting point.', 0),
  ('f7c31534-6526-4653-be88-b2f852b16a1f', 'e277c175-61a0-487d-98f2-25f031973da1', '4e2e6a1d-45a2-4cb7-bf49-d28176538854', 'subtopic'::public.curated_course_node_type, 'Time averages', 'Time averages identifies a specific object, distinction, or relationship within stationarity and ergodicity. Learners need to recognize and use it before combining this module''s ideas in later work. After wss, time averages supplies what is needed to address autocorrelation properties.', 1),
  ('d1bcb624-62ac-41b8-9e71-f1601b924c04', 'e277c175-61a0-487d-98f2-25f031973da1', '4e2e6a1d-45a2-4cb7-bf49-d28176538854', 'subtopic'::public.curated_course_node_type, 'Autocorrelation properties', 'Autocorrelation properties identifies a specific object, distinction, or relationship within stationarity and ergodicity. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, autocorrelation properties carries the completed idea into spectral analysis and lti systems.', 2),
  ('492872a6-44bc-48fb-80bf-25c398199450', 'e277c175-61a0-487d-98f2-25f031973da1', null, 'topic'::public.curated_course_node_type, 'Spectral analysis and LTI systems', 'This module builds directly on stationarity and ergodicity and develops spectral analysis and lti systems. It belongs here because its methods and distinctions are prerequisites for canonical processes.', 10),
  ('e64398cb-b1b3-4c10-a719-656581dd9f75', 'e277c175-61a0-487d-98f2-25f031973da1', '492872a6-44bc-48fb-80bf-25c398199450', 'subtopic'::public.curated_course_node_type, 'PSD', 'PSD identifies a specific object, distinction, or relationship within spectral analysis and lti systems. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before wiener–khinchin because that next topic assumes this starting point.', 0),
  ('526d09c7-9d48-47cd-832d-69f30092144d', 'e277c175-61a0-487d-98f2-25f031973da1', '492872a6-44bc-48fb-80bf-25c398199450', 'subtopic'::public.curated_course_node_type, 'Wiener–Khinchin', 'Wiener–Khinchin identifies a specific object, distinction, or relationship within spectral analysis and lti systems. Learners need to recognize and use it before combining this module''s ideas in later work. After psd, wiener–khinchin supplies what is needed to address noise through filters.', 1),
  ('504a056b-e75e-4129-b889-514dca6b64ac', 'e277c175-61a0-487d-98f2-25f031973da1', '492872a6-44bc-48fb-80bf-25c398199450', 'subtopic'::public.curated_course_node_type, 'Noise through filters', 'Noise through filters identifies a specific object, distinction, or relationship within spectral analysis and lti systems. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, noise through filters carries the completed idea into canonical processes.', 2),
  ('986dd91f-ccf1-4216-9ff5-8df9747af8b2', 'e277c175-61a0-487d-98f2-25f031973da1', null, 'topic'::public.curated_course_node_type, 'Canonical processes', 'This culminating module draws on spectral analysis and lti systems and develops canonical processes. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('7b705d8e-19e6-4950-98ba-05fd613ef530', 'e277c175-61a0-487d-98f2-25f031973da1', '986dd91f-ccf1-4216-9ff5-8df9747af8b2', 'subtopic'::public.curated_course_node_type, 'Poisson process', 'Poisson process gives canonical processes a reusable representation for organizing assumptions, variables, and relationships before analysis begins. It appears before markov chains because that next topic assumes this starting point.', 0),
  ('604c7cf9-49d7-43ba-815f-f4f6980c4758', 'e277c175-61a0-487d-98f2-25f031973da1', '986dd91f-ccf1-4216-9ff5-8df9747af8b2', 'subtopic'::public.curated_course_node_type, 'Markov chains', 'Markov chains identifies a specific object, distinction, or relationship within canonical processes. Learners need to recognize and use it before combining this module''s ideas in later work. After poisson process, markov chains supplies what is needed to address gaussian processes.', 1),
  ('133aef94-503f-4d89-bf36-fa1886c1b70f', 'e277c175-61a0-487d-98f2-25f031973da1', '986dd91f-ccf1-4216-9ff5-8df9747af8b2', 'subtopic'::public.curated_course_node_type, 'Gaussian processes', 'Gaussian processes gives canonical processes a reusable representation for organizing assumptions, variables, and relationships before analysis begins. After markov chains, gaussian processes supplies what is needed to address queueing glimpse.', 2),
  ('337c623e-837b-4f8e-bee6-a4fd11eb6339', 'e277c175-61a0-487d-98f2-25f031973da1', '986dd91f-ccf1-4216-9ff5-8df9747af8b2', 'subtopic'::public.curated_course_node_type, 'Queueing glimpse', 'Queueing glimpse identifies a specific object, distinction, or relationship within canonical processes. Learners need to recognize and use it before combining this module''s ideas in later work. As the final course topic, queueing glimpse requires ideas from the complete path to be integrated and transferred.', 3);
insert into public.learning_paths (
